#!/usr/bin/env python3
"""Regenerate docs/model-lab/EXPERIMENT_RESULTS.md from model_lab/results/*.json (no number is typed by hand)."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
R = lambda n: json.load(open(os.path.join(ROOT, "model_lab", "results", n)))

def table(res, title):
    rows = sorted(res["pooled"].items(), key=lambda kv: kv[1]["logloss"])
    out = [f"### {title}", "", f"Folds {res['folds']}; every row fitted on earlier seasons only. dLL = log-loss minus the published-score baseline (B), negative is better; the interval is a 95% paired cluster bootstrap over (season, week). `folds<B` = folds where it beat B.", "",
           "| model | n | log loss | Brier | AUC | top-15/wk | top-30/wk | dLL vs B [95% CI] | folds<B |", "|---|---:|---:|---:|---:|---:|---:|---|---:|"]
    for k, m in rows:
        out.append(f"| {k} | {m['n']} | {m['logloss']:.4f} | {m['brier']:.4f} | {m['auc']:.3f} | {m['top15']*100:.1f}% | {m['top30']*100:.1f}% | {m['d_logloss_vs_v2']:+.4f} [{m['d_lo']:+.4f}, {m['d_hi']:+.4f}] | {m['folds_better_than_v2']}/{len(res['folds'])} |")
    return "\n".join(out)

def per_fold(res, keys):
    out = ["| model | " + " | ".join(f"{f} LL / AUC" for f in res["folds"]) + " |", "|---|" + "---|" * len(res["folds"])]
    for k in keys:
        out.append(f"| {k} | " + " | ".join(f"{res['per_fold'][k][str(f)]['logloss']:.4f} / {res['per_fold'][k][str(f)]['auc']:.3f}" for f in res["folds"]) + " |")
    return "\n".join(out)

def calib(res, k):
    out = [f"| decile | n | mean predicted | observed |", "|---:|---:|---:|---:|"]
    out += [f"| {b['bin']} | {b['n']} | {b['mean_pred']:.3f} | {b['observed']:.3f} |" for b in res["pooled"][k]["calibration"]]
    return "\n".join(out)

sel, hold, ana = R("nfl_td_selection.json"), R("nfl_td_holdout.json"), R("nfl_td_discovery.json")
doc = ["# EXPERIMENT RESULTS: NFL anytime touchdown", "",
       "Generated by `model_lab/make_reports.py` from `model_lab/results/*.json`. Reproduce: `python model_lab/build_nfl_tables.py 2021 2022 2023 2024 2025`, then `python model_lab/nfl_td_walkforward.py selection`, `python model_lab/nfl_td_discovery.py`, and ONCE `python model_lab/nfl_td_walkforward.py holdout`.", "",
       f"Experiments run: {sel['n_experiments']} model/feature configurations on the selection folds, each also scored once on the holdout. Nothing outside this table was tried and discarded.", "",
       table(sel, "Selection folds (2022, 2023, 2024)"), "", "Per-fold stability of the main candidates:", "",
       per_fold(sel, ["A_base_by_position", "B_v2_platt", "C_v3_xtd_shadow_platt", "F4_lr_opp_team", "G_lr_all", "H_gbm_all", "K_ens_lr_gbm"]), "",
       table(hold, "Final holdout (2025): run once, after the selection above was fixed"), "",
       "### Calibration of the published score (mapped to a probability) and the ensemble", "", "Selection folds, pooled. Published score (B):", "", calib(sel, "B_v2_platt"), "", "Ensemble (K):", "", calib(sel, "K_ens_lr_gbm"), "",
       "Holdout 2025, published score (B):", "", calib(hold, "B_v2_platt"), "", "Holdout 2025, ensemble (K):", "", calib(hold, "K_ens_lr_gbm"), "",
       "### Leave-one-feature-family-out (full logistic model, selection folds)", "", "dLL = full model minus the model without that family; negative means the family helps.", "",
       "| family | log loss without | dLL [95% CI] |", "|---|---:|---|"]
for g, v in ana["logo"].items():
    doc.append(f"| {g} | {v['without_logloss']:.4f} | {v['d_logloss_full_minus_without']:+.4f} [{v['lo']:+.4f}, {v['hi']:+.4f}] |")
doc += ["", "### Segments (full logistic vs published score mapped to a probability, selection folds)", "", "| segment | n | base rate | LL full | LL published | dLL [95% CI] | AUC full / published |", "|---|---:|---:|---:|---:|---|---|"]
for k, v in ana["segments"].items():
    doc.append(f"| {k} | {v['n']} | {v['base_rate']:.3f} | {v['ll_full']:.4f} | {v['ll_v2']:.4f} | {v['d']:+.4f} [{v['lo']:+.4f}, {v['hi']:+.4f}] | {v['auc_full']:.3f} / {v['auc_v2']:.3f} |")
doc += ["", "### Hit rate by within-week rank of the published score (selection folds)", "", "| rank | n | anytime-TD rate |", "|---|---:|---:|"]
for k, v in ana["rank_buckets_v2"].items():
    doc.append(f"| {k} | {v['n']} | {v['hit']*100:.1f}% |")
doc += ["", "### Pre-registered discovery tests (Holm over 10)", "", "| feature | mechanism | dLL [95% CI] | p | Holm threshold | coverage | result |", "|---|---|---|---:|---:|---:|---|"]
for k, v in sorted(ana["discovery"].items(), key=lambda kv: kv[1].get("p", 9)):
    if "p" not in v: continue
    doc.append(f"| {k} | {v['why']} | {v['d_logloss']:+.5f} [{v['lo']:+.5f}, {v['hi']:+.5f}] | {v['p']:.3f} | {v['holm_threshold']:.4f} | {v['coverage']*100:.0f}% | {'significant' if v['significant_after_holm'] else 'not significant'} |")
q = ana["qb"]
doc += ["", "### Quarterbacks (anytime TD = rushing + receiving)", "", f"{q['n']} QB-weeks, base rate {q['base_rate']:.3f}. Logistic on rushing opportunity + team context: log loss {q['lr']['logloss']:.4f}, AUC {q['lr']['auc']:.3f}; train-base-rate baseline {q['baseline']['logloss']:.4f}; dLL {q['d']:+.4f} [{q['lo']:+.4f}, {q['hi']:+.4f}]."]
open(os.path.join(ROOT, "docs", "model-lab", "EXPERIMENT_RESULTS.md"), "w").write("\n".join(doc) + "\n")
print("wrote EXPERIMENT_RESULTS.md")
